shell_commands:
node --input-type=module -e "
import Ajv from 'ajv';
const a = new Ajv({strict: false, validateFormats: false});
const s = {type:'object',properties:{location:{type:'string'}},required:['location']};
a.validate(s, {});
console.log('missing:', JSON.stringify(a.errorsText(a.errors)));
a.validate(s, {location: 123456789});
console.log('wrongtype:', JSON.stringify(a.errorsText(a.errors)));
a.validate(s, {location:'Paris', extra:'x'});
console.log('extra-ok:', a.validate(s, {location:'Paris', extra:'x'}));
a.validate(s, {location:'Paris', extra:'x', ssn:'111-22-3333'});
console.log('valid:', a.errors);
"
